//! Publisher signatures and version floors for VPK2 packages.
//!
//! The root task links this as an object and calls it from `valid_package`
//! (system/supervisor/supervisor.c), so the factory catalog, an installed
//! catalog bank and the install inbox all pass through it. A record is
//!
//!   header[24] | image[size] | "VSG1" | key_id | version | target | r[32] | s[32]
//!
//! and the ECDSA P-256 signature covers every byte before it (SHA-256). The
//! keys an image trusts and its target tag are generated by the build
//! (image/packages/sign.py) into the file named by VIOLET_PACKAGE_KEYS_RS.
//! Anything that does not verify is refused: there is no unsigned fallback.
#![cfg_attr(not(test), no_std)]
#![allow(dead_code)]

include!(env!("VIOLET_PACKAGE_KEYS_RS"));

/// Full-system update manifests, signed by the same keys (ota.rs).
#[path = "ota.rs"]
pub mod ota;

pub const HEADER: usize = 24;
/// Trailer bytes under the signature: magic, key ID, version, target.
pub const SIGNED_TRAILER: usize = 16;
pub const TRAILER: usize = SIGNED_TRAILER + 64;
const VPK2: u32 = 0x324b_5056;
const VSG1: u32 = 0x3147_5356;

#[derive(Debug, PartialEq, Clone, Copy)]
pub enum Refusal {
    Truncated,
    /// Not a VPK2 record (an unsigned VPK1 lands here).
    Format,
    Trailer,
    Target,
    /// Signed by a key this image does not pin.
    Key,
    Signature,
}

pub type Sha256 = fn(&[u8]) -> [u8; 32];
pub type P256Verify = fn(&[u8; 65], &[u8; 32], &[u8; 64]) -> bool;

fn word(bytes: &[u8], at: usize) -> u32 {
    u32::from_le_bytes([bytes[at], bytes[at + 1], bytes[at + 2], bytes[at + 3]])
}

/// Signatures already checked, so a group restart hashes each package again
/// but does not repeat the curve arithmetic. An entry is the digest of the
/// signed bytes, the key that signed them and the signature itself.
pub struct Cache {
    entries: [([u8; 32], u32, [u8; 64]); Cache::SLOTS],
    used: usize,
    next: usize,
}

impl Cache {
    /// More than the packages of one catalog; past that, old entries are
    /// evicted and only time is lost.
    pub const SLOTS: usize = 16;
    pub const fn new() -> Self {
        Cache { entries: [([0; 32], 0, [0; 64]); Cache::SLOTS], used: 0, next: 0 }
    }
    fn holds(&self, digest: &[u8; 32], key: u32, signature: &[u8; 64]) -> bool {
        self.entries[..self.used].iter().any(|e| e.1 == key && e.0 == *digest && e.2 == *signature)
    }
    fn insert(&mut self, digest: [u8; 32], key: u32, signature: [u8; 64]) {
        self.entries[self.next] = (digest, key, signature);
        self.next = (self.next + 1) % Cache::SLOTS;
        if self.used < Cache::SLOTS {
            self.used += 1;
        }
    }
}

/// The security version of the record at the start of `bytes`, once its
/// signature by one of `keys` for `target` has been checked. `bytes` may run
/// past the record (a catalog holds several); nothing beyond it is read.
pub fn check(
    bytes: &[u8],
    target: u32,
    keys: &[(u32, [u8; 65])],
    sha256: Sha256,
    p256: P256Verify,
    cache: &mut Cache,
) -> Result<u32, Refusal> {
    if bytes.len() < HEADER + TRAILER {
        return Err(Refusal::Truncated);
    }
    if word(bytes, 0) != VPK2 {
        return Err(Refusal::Format);
    }
    let size = word(bytes, 16) as usize;
    if size > bytes.len() - HEADER - TRAILER {
        return Err(Refusal::Truncated);
    }
    let trailer = HEADER + size;
    let (key_id, version) = (word(bytes, trailer + 4), word(bytes, trailer + 8));
    if word(bytes, trailer) != VSG1 || version == 0 {
        return Err(Refusal::Trailer);
    }
    if word(bytes, trailer + 12) != target {
        return Err(Refusal::Target);
    }
    let Some((_, key)) = keys.iter().find(|k| k.0 == key_id) else {
        return Err(Refusal::Key);
    };
    let signed = trailer + SIGNED_TRAILER;
    let digest = sha256(&bytes[..signed]);
    let mut signature = [0u8; 64];
    signature.copy_from_slice(&bytes[signed..signed + 64]);
    if cache.holds(&digest, key_id, &signature) {
        return Ok(version);
    }
    if !p256(key, &digest, &signature) {
        return Err(Refusal::Signature);
    }
    cache.insert(digest, key_id, signature);
    Ok(version)
}

/// Version floors, by component ID.
///
/// `factory` is the version each component has in the boot image's own
/// catalog: an installed catalog holding anything older is not booted, so a
/// new boot image retires older signed packages.
///
/// A package is installed only at or above every floor: `factory`, `proven`
/// (the highest version of each component in any catalog that ran healthy
/// since power-on) and `running` (the catalog running now: its packages and
/// the floor record it carries). A catalog that faults in its trial and is
/// rejected takes its `running` floors with it, so the version that was
/// running before can be installed again.
///
/// The floor record is how floors outlive a removal and a reboot. Every
/// catalog the supervisor writes ends with one: the highest version seen of
/// each component, where that is above the factory version (so a removed
/// component leaves its version behind). It is
///
///   "VFL1" | count | count x (id, version)      ids ascending, versions not 0
///
/// inside the catalog's size and CRC. It is not signed: whoever can rewrite a
/// catalog bank can drop it (README.md, "What is not covered").
pub struct Floors {
    factory: [u32; Floors::IDS],
    proven: [u32; Floors::IDS],
    running: [u32; Floors::IDS],
}

const VFL1: u32 = 0x314c_4656;

impl Floors {
    pub const IDS: usize = 32;
    /// The most bytes a floor record takes.
    pub const RECORD: usize = 8 + 8 * Floors::IDS;
    pub const fn new() -> Self {
        Floors { factory: [0; Floors::IDS], proven: [0; Floors::IDS], running: [0; Floors::IDS] }
    }
    /// A package of the boot image's own catalog.
    pub fn factory(&mut self, id: u32, version: u32) {
        if let Some(floor) = self.factory.get_mut(id as usize) {
            *floor = version;
            self.proven[id as usize] = self.proven[id as usize].max(version);
        }
    }
    /// A catalog is about to start: forget what the last one claimed.
    pub fn begin(&mut self) {
        self.running = [0; Floors::IDS];
    }
    /// A package of the catalog that is starting.
    pub fn ran(&mut self, id: u32, version: u32) {
        if let Some(floor) = self.running.get_mut(id as usize) {
            *floor = (*floor).max(version);
        }
    }
    /// The running catalog stayed healthy: its floors now hold until power-off.
    pub fn confirm(&mut self) {
        for id in 0..Floors::IDS {
            self.proven[id] = self.proven[id].max(self.running[id]);
        }
    }
    /// May a catalog holding this package boot?
    pub fn boots(&self, id: u32, version: u32) -> bool {
        self.factory.get(id as usize).is_some_and(|floor| version != 0 && version >= *floor)
    }
    /// May this package replace what is installed?
    pub fn installs(&self, id: u32, version: u32) -> bool {
        self.boots(id, version) && version >= self.proven[id as usize] && version >= self.running[id as usize]
    }
    /// The floor record of the running catalog: its floors join `running`.
    /// Only for a record `record_floor` accepts.
    pub fn load(&mut self, record: &[u8]) {
        if record_floor(record, 0).is_none() {
            return;
        }
        for entry in 0..word(record, 4) as usize {
            self.ran(word(record, 8 + 8 * entry), word(record, 12 + 8 * entry));
        }
    }
    /// Write the floor record for a catalog being composed, in which component
    /// `id` becomes `version` (0 when it is removed). Returns its length: 0
    /// when no floor is above the factory's (no record is written), or when
    /// `out` is too small (callers leave Floors::RECORD bytes).
    pub fn record(&self, out: &mut [u8], id: u32, version: u32) -> usize {
        let mut count = 0;
        for at in 0..Floors::IDS {
            let new = if at as u32 == id { version } else { 0 };
            let floor = self.proven[at].max(self.running[at]).max(new);
            if floor <= self.factory[at] {
                continue;
            }
            let Some(entry) = out.get_mut(8 + 8 * count..16 + 8 * count) else {
                return 0;
            };
            entry[..4].copy_from_slice(&(at as u32).to_le_bytes());
            entry[4..].copy_from_slice(&floor.to_le_bytes());
            count += 1;
        }
        if count == 0 {
            return 0;
        }
        out[..4].copy_from_slice(&VFL1.to_le_bytes());
        out[4..8].copy_from_slice(&(count as u32).to_le_bytes());
        8 + 8 * count
    }
}

/// The floor a catalog's own record sets for `id` (0 when it has none), or
/// None unless `record` is exactly one well-formed floor record.
pub fn record_floor(record: &[u8], id: u32) -> Option<u32> {
    if record.len() < 16 || word(record, 0) != VFL1 {
        return None;
    }
    let count = word(record, 4) as usize;
    if count == 0 || count > Floors::IDS || record.len() != 8 + 8 * count {
        return None;
    }
    let (mut floor, mut last) = (0, None);
    for entry in 0..count {
        let (at, version) = (word(record, 8 + 8 * entry), word(record, 12 + 8 * entry));
        if at as usize >= Floors::IDS || version == 0 || last.is_some_and(|l| at <= l) {
            return None;
        }
        last = Some(at);
        if at == id {
            floor = version;
        }
    }
    Some(floor)
}

/// Whether a fault may throw away the installed catalog.
///
/// A catalog is on trial from the moment it is committed until it has run
/// healthy for the supervisor's health period. A fault during the trial
/// rejects it (the previous catalog, or the factory one, runs again). After
/// the trial, and for a catalog found at power-on, a fault only restarts the
/// same catalog: a crash can no longer be used to bring back older packages.
pub struct Trial {
    on: bool,
}

impl Trial {
    pub const fn new() -> Self {
        Trial { on: false }
    }
    /// A new catalog was committed and is about to start.
    pub fn installed(&mut self) {
        self.on = true;
    }
    /// The running catalog stayed healthy for the whole period.
    pub fn healthy(&mut self) {
        self.on = false;
    }
    /// A process of the installed catalog faulted: reject the catalog?
    /// Whatever runs next was accepted before, so it is not on trial.
    pub fn fault_rejects(&mut self) -> bool {
        core::mem::replace(&mut self.on, false)
    }
}

/// An ASN.1 ECDSA signature, SEQUENCE { INTEGER r, INTEGER s }, as r[32] | s[32].
/// For the developer's detached USB signature (supervisor.c, signed_update).
pub fn der_signature(der: &[u8]) -> Option<[u8; 64]> {
    if der.len() < 8 || der[0] != 0x30 || der[1] & 0x80 != 0 || der[1] as usize != der.len() - 2 {
        return None;
    }
    let mut out = [0u8; 64];
    let mut at = 2;
    for half in 0..2 {
        if at + 2 > der.len() || der[at] != 2 {
            return None;
        }
        let len = der[at + 1] as usize;
        let end = at + 2 + len;
        if len == 0 || len > 33 || end > der.len() || der[at + 2] & 0x80 != 0 {
            return None;
        }
        let mut digits = &der[at + 2..end];
        if digits.len() == 33 {
            if digits[0] != 0 {
                return None;
            }
            digits = &digits[1..];
        }
        out[half * 32 + 32 - digits.len()..half * 32 + 32].copy_from_slice(digits);
        at = end;
    }
    (at == der.len()).then_some(out)
}

#[cfg(not(test))]
mod root {
    use super::*;
    extern "C" {
        fn package_sha256(data: *const u8, len: usize, out: *mut u8);
        fn package_p256_verify(key: *const u8, hash: *const u8, signature: *const u8) -> i32;
    }
    fn sha256(data: &[u8]) -> [u8; 32] {
        let mut out = [0; 32];
        unsafe { package_sha256(data.as_ptr(), data.len(), out.as_mut_ptr()) };
        out
    }
    fn p256(key: &[u8; 65], hash: &[u8; 32], signature: &[u8; 64]) -> bool {
        unsafe { package_p256_verify(key.as_ptr(), hash.as_ptr(), signature.as_ptr()) == 1 }
    }
    static mut CACHE: Cache = Cache::new();
    static mut FLOORS: Floors = Floors::new();
    static mut TRIAL: Trial = Trial::new();
    unsafe fn floors() -> &'static mut Floors {
        &mut *core::ptr::addr_of_mut!(FLOORS)
    }
    unsafe fn bytes<'a>(data: *const u8, len: u32) -> &'a [u8] {
        if data.is_null() || len as usize > 1 << 20 {
            return &[];
        }
        core::slice::from_raw_parts(data, len as usize)
    }

    /// The record's security version (never 0), or 0 when it must not run.
    /// `limit` is how many bytes are readable at `package`.
    #[no_mangle]
    unsafe extern "C" fn package_verify(package: *const u8, limit: u32) -> u32 {
        if package.is_null() || limit as usize > 1 << 20 {
            return 0;
        }
        check(bytes(package, limit), TARGET, KEYS, sha256, p256, &mut *core::ptr::addr_of_mut!(CACHE)).unwrap_or(0)
    }
    #[no_mangle]
    unsafe extern "C" fn package_floor_factory(id: u32, version: u32) {
        floors().factory(id, version)
    }
    #[no_mangle]
    unsafe extern "C" fn package_floor_begin() {
        floors().begin()
    }
    #[no_mangle]
    unsafe extern "C" fn package_floor_ran(id: u32, version: u32) {
        floors().ran(id, version)
    }
    #[no_mangle]
    unsafe extern "C" fn package_floor_boots(id: u32, version: u32) -> bool {
        floors().boots(id, version)
    }
    #[no_mangle]
    unsafe extern "C" fn package_floor_installs(id: u32, version: u32) -> bool {
        floors().installs(id, version)
    }
    /// The floor a catalog's record sets for `id`, or 0xffffffff (which no
    /// package meets) unless the `len` bytes at `record` are one valid record.
    #[no_mangle]
    unsafe extern "C" fn package_floor_record_floor(record: *const u8, len: u32, id: u32) -> u32 {
        record_floor(bytes(record, len), id).unwrap_or(u32::MAX)
    }
    #[no_mangle]
    unsafe extern "C" fn package_floor_load(record: *const u8, len: u32) {
        floors().load(bytes(record, len))
    }
    /// Writes the floor record of a catalog in which `id` becomes `version`
    /// (0: removed) into `room` bytes at `out`; returns its length.
    #[no_mangle]
    unsafe extern "C" fn package_floor_record(out: *mut u8, room: u32, id: u32, version: u32) -> u32 {
        if out.is_null() || room as usize > 1 << 20 {
            return 0;
        }
        floors().record(core::slice::from_raw_parts_mut(out, room as usize), id, version) as u32
    }
    #[no_mangle]
    unsafe extern "C" fn package_trial_installed() {
        (*core::ptr::addr_of_mut!(TRIAL)).installed()
    }
    /// The running catalog stayed healthy: its trial ends and its floors stay.
    #[no_mangle]
    unsafe extern "C" fn package_trial_healthy() {
        (*core::ptr::addr_of_mut!(TRIAL)).healthy();
        floors().confirm()
    }
    #[no_mangle]
    unsafe extern "C" fn package_trial_fault_rejects() -> bool {
        (*core::ptr::addr_of_mut!(TRIAL)).fault_rejects()
    }
    /// 1 when the `len` bytes at `der` are an ASN.1 signature by `key` (an
    /// uncompressed P-256 point) over the SHA-256 of the `size` bytes at `data`.
    #[no_mangle]
    unsafe extern "C" fn package_detached_verify(key: *const u8, data: *const u8, size: u32, der: *const u8, len: u32) -> bool {
        if key.is_null() || data.is_null() || der.is_null() || size as usize > 1 << 20 || len > 72 {
            return false;
        }
        let Some(signature) = der_signature(bytes(der, len)) else {
            return false;
        };
        p256(&*(key as *const [u8; 65]), &sha256(bytes(data, size)), &signature)
    }
    /// This boot image's own system version (VIOLET_SYSTEM_VERSION at build time).
    const SYSTEM_VERSION: u32 = super::ota::system_version();
    /// A full-system update's manifest, the first ota::MANIFEST bytes at
    /// `manifest`, for an inactive slot of `slot_sectors` sectors. Returns
    /// its version (never 0) when it is signed by a pinned key for this
    /// target and is not older than this system; then `*sectors` is the
    /// image's length in sectors. When `digest` is not null it must also be
    /// the manifest's digest (what Storage read back). Otherwise returns 0
    /// and `*why` is the refusal (1 format, 2 target, 3 key, 4 signature,
    /// 5 version, 6 size, 7 digest).
    #[no_mangle]
    unsafe extern "C" fn ota_verify(manifest: *const u8, slot_sectors: u32, digest: *const u8, sectors: *mut u32, why: *mut u32) -> u32 {
        use super::ota::{check, matches, Refusal, MANIFEST};
        if manifest.is_null() || sectors.is_null() || why.is_null() {
            return 0;
        }
        let result = check(bytes(manifest, MANIFEST as u32), TARGET, KEYS, SYSTEM_VERSION, slot_sectors, sha256, p256)
            .and_then(|m| if digest.is_null() { Ok(m) } else { matches(&m, &*(digest as *const [u8; 32])).map(|_| m) });
        match result {
            Ok(m) => {
                *sectors = m.sectors();
                *why = 0;
                m.version
            }
            Err(r) => {
                *sectors = 0;
                *why = match r {
                    Refusal::Format => 1,
                    Refusal::Target => 2,
                    Refusal::Key => 3,
                    Refusal::Signature => 4,
                    Refusal::Version => 5,
                    Refusal::Size => 6,
                    Refusal::Digest => 7,
                };
                0
            }
        }
    }
    /// The version in the image, where tools/ota_bundle.py finds it.
    #[used]
    static SYSTEM_VERSION_NOTE: [u8; super::ota::NOTE] = super::ota::version_note(SYSTEM_VERSION);
    #[no_mangle]
    unsafe extern "C" fn ota_system_version() -> u32 {
        // Read through the note so the linker keeps it.
        let note = core::ptr::read_volatile(core::ptr::addr_of!(SYSTEM_VERSION_NOTE));
        super::ota::note_version(&note).unwrap_or(SYSTEM_VERSION)
    }
    static mut MARK: super::ota::Mark = super::ota::Mark::new();
    /// The components (re)start: the slot is not marked until they run healthy.
    #[no_mangle]
    unsafe extern "C" fn ota_mark_restart() {
        (*core::ptr::addr_of_mut!(MARK)).restart()
    }
    /// Whether to ask Storage to mark the running slot now (ota.rs `Mark`).
    #[no_mangle]
    unsafe extern "C" fn ota_mark_due(healthy: bool, now: u32) -> bool {
        (*core::ptr::addr_of_mut!(MARK)).due(healthy, now)
    }
    #[no_mangle]
    unsafe extern "C" fn ota_mark_result(ok: bool, now: u32, second: u32) {
        (*core::ptr::addr_of_mut!(MARK)).result(ok, now, second)
    }
}

// Host tests (system/package-manager/test_verify.sh): the real BearSSL built
// for the host, and packages signed by image/packages/sign.py with openssl.
#[cfg(test)]
mod tests {
    use super::*;
    use std::sync::atomic::{AtomicUsize, Ordering};
    extern "C" {
        fn package_sha256(data: *const u8, len: usize, out: *mut u8);
        fn package_p256_verify(key: *const u8, hash: *const u8, signature: *const u8) -> i32;
    }
    static CURVE_CHECKS: AtomicUsize = AtomicUsize::new(0);
    fn sha256(data: &[u8]) -> [u8; 32] {
        let mut out = [0; 32];
        unsafe { package_sha256(data.as_ptr(), data.len(), out.as_mut_ptr()) };
        out
    }
    fn p256(key: &[u8; 65], hash: &[u8; 32], signature: &[u8; 64]) -> bool {
        CURVE_CHECKS.fetch_add(1, Ordering::SeqCst);
        unsafe { package_p256_verify(key.as_ptr(), hash.as_ptr(), signature.as_ptr()) == 1 }
    }
    fn fixture(name: &str) -> Vec<u8> {
        let dir = std::env::var("VPK_FIXTURES").expect("VPK_FIXTURES");
        std::fs::read(format!("{dir}/{name}")).unwrap()
    }
    fn verdict(bytes: &[u8]) -> Result<u32, Refusal> {
        check(bytes, TARGET, KEYS, sha256, p256, &mut Cache::new())
    }
    fn crc32(bytes: &[u8]) -> u32 {
        let mut v = !0u32;
        for b in bytes {
            v ^= *b as u32;
            for _ in 0..8 {
                v = (v >> 1) ^ ((0u32.wrapping_sub(v & 1)) & 0xedb8_8320);
            }
        }
        !v
    }

    #[test]
    fn signed_packages_verify_and_report_their_version() {
        assert_eq!(verdict(&fixture("good.vpk")), Ok(3));
        // The release root (key 1) is pinned beside the developer key in this fixture set.
        assert_eq!(verdict(&fixture("release.vpk")), Ok(7));
        // A record inside a catalog is followed by other bytes.
        let mut longer = fixture("good.vpk");
        longer.extend_from_slice(&[0xa5; 100]);
        assert_eq!(verdict(&longer), Ok(3));
    }

    #[test]
    fn every_signed_byte_is_covered() {
        let good = fixture("good.vpk");
        let size = word(&good, 16) as usize;
        assert_eq!(good.len(), HEADER + size + TRAILER);
        // Header fields (ABI, ID, code, size is tested apart, CRC), the image's
        // first, middle and last bytes, and the trailer's key, version and target.
        let mut places = vec![4, 8, 12, 20, 23, HEADER, HEADER + size / 2, HEADER + size - 1];
        places.extend(HEADER + size + 4..HEADER + size + SIGNED_TRAILER);
        for at in places {
            for bit in [0, 7] {
                let mut bad = good.clone();
                bad[at] ^= 1 << bit;
                let result = verdict(&bad);
                assert!(result.is_err(), "flip at {at} bit {bit} accepted: {result:?}");
            }
        }
        // And every byte of the signature.
        for at in good.len() - 64..good.len() {
            let mut bad = good.clone();
            bad[at] ^= 0x10;
            assert_eq!(verdict(&bad), Err(Refusal::Signature), "signature byte {at}");
        }
    }

    #[test]
    fn a_relabelled_package_fails_even_with_a_fresh_checksum() {
        // Another component ID, and a patched image with its CRC recomputed:
        // both pass a CRC-only check and must fail here.
        let good = fixture("good.vpk");
        let size = word(&good, 16) as usize;
        let mut other_id = good.clone();
        other_id[8..12].copy_from_slice(&6u32.to_le_bytes());
        assert_eq!(verdict(&other_id), Err(Refusal::Signature));
        let mut patched = good.clone();
        patched[HEADER] ^= 0xff;
        let crc = crc32(&patched[HEADER..HEADER + size]);
        patched[20..24].copy_from_slice(&crc.to_le_bytes());
        assert_eq!(verdict(&patched), Err(Refusal::Signature));
        // A higher version claimed for an old signature.
        let mut newer = good.clone();
        newer[HEADER + size + 8..HEADER + size + 12].copy_from_slice(&9u32.to_le_bytes());
        assert_eq!(verdict(&newer), Err(Refusal::Signature));
    }

    #[test]
    fn unsigned_truncated_and_foreign_packages_are_refused() {
        let good = fixture("good.vpk");
        let size = word(&good, 16) as usize;
        // The old unsigned format, with and without bytes where a trailer would be.
        let mut vpk1 = good.clone();
        vpk1[..4].copy_from_slice(b"VPK1");
        assert_eq!(verdict(&vpk1), Err(Refusal::Format));
        assert_eq!(verdict(&fixture("unsigned.vpk")), Err(Refusal::Truncated));
        let mut padded = fixture("unsigned.vpk");
        padded.extend_from_slice(&[0; TRAILER]);
        assert_eq!(verdict(&padded), Err(Refusal::Trailer));
        // Readable bytes end before the record does.
        for cut in [0, 1, HEADER, HEADER + TRAILER - 1, good.len() - 65, good.len() - 1] {
            assert_eq!(verdict(&good[..cut]), Err(Refusal::Truncated), "cut {cut}");
        }
        // A size field that points past the readable bytes, or wraps.
        for claimed in [size as u32 + 1, 0x7fff_ffff, 0xffff_ffff, 0xffff_ff98] {
            let mut bad = good.clone();
            bad[16..20].copy_from_slice(&claimed.to_le_bytes());
            assert_eq!(verdict(&bad), Err(Refusal::Truncated), "size {claimed:#x}");
        }
        // A shorter size makes the trailer land inside the image.
        let mut short = good.clone();
        short[16..20].copy_from_slice(&(size as u32 - 4).to_le_bytes());
        assert_eq!(verdict(&short), Err(Refusal::Trailer));
        // Version 0 is not a version.
        assert_eq!(verdict(&fixture("version0.vpk")), Err(Refusal::Trailer));
        // Signed correctly, for the other board.
        assert_eq!(verdict(&fixture("other-target.vpk")), Err(Refusal::Target));
        // Signed correctly by a key this image does not pin, under its own ID
        // and under a pinned ID.
        assert_eq!(verdict(&fixture("unknown-key.vpk")), Err(Refusal::Key));
        assert_eq!(verdict(&fixture("wrong-key.vpk")), Err(Refusal::Signature));
    }

    #[test]
    fn a_release_image_refuses_the_developer_key() {
        // A release image pins key 1 alone.
        let release: Vec<(u32, [u8; 65])> = KEYS.iter().filter(|k| k.0 == 1).copied().collect();
        assert_eq!(release.len(), 1);
        let run = |name: &str| check(&fixture(name), TARGET, &release, sha256, p256, &mut Cache::new());
        assert_eq!(run("release.vpk"), Ok(7));
        assert_eq!(run("good.vpk"), Err(Refusal::Key));
        // No keys at all: nothing runs.
        assert_eq!(check(&fixture("good.vpk"), TARGET, &[], sha256, p256, &mut Cache::new()), Err(Refusal::Key));
    }

    #[test]
    fn the_cache_skips_only_identical_signed_bytes() {
        let good = fixture("good.vpk");
        let size = word(&good, 16) as usize;
        let mut cache = Cache::new();
        let run = |bytes: &[u8], cache: &mut Cache| {
            let before = CURVE_CHECKS.load(Ordering::SeqCst);
            let result = check(bytes, TARGET, KEYS, sha256, p256, cache);
            (result, CURVE_CHECKS.load(Ordering::SeqCst) > before)
        };
        // Other tests run in parallel and also count curve checks, so only
        // "no curve check happened" is asserted from the counter; a refusal
        // proves a check ran.
        assert_eq!(run(&good, &mut cache).0, Ok(3));
        let mut bad = good.clone();
        bad[HEADER + 9] ^= 1;
        assert_eq!(run(&bad, &mut cache).0, Err(Refusal::Signature));
        let mut forged = good.clone();
        let last = forged.len() - 1;
        forged[last] ^= 1;
        assert_eq!(run(&forged, &mut cache).0, Err(Refusal::Signature));
        let mut claimed = good.clone();
        claimed[HEADER + size + 4] = 1; // same bytes, attributed to key 1
        assert!(run(&claimed, &mut cache).0.is_err());
        // A refused package is never remembered.
        assert_eq!(run(&bad, &mut cache).0, Err(Refusal::Signature));
        // More packages than slots: old entries are evicted, results stay right.
        for _ in 0..Cache::SLOTS + 3 {
            let digest = [cache.next as u8; 32];
            cache.insert(digest, 99, [0; 64]);
        }
        assert_eq!(run(&good, &mut cache).0, Ok(3));
    }

    #[test]
    fn the_cache_avoids_repeating_curve_arithmetic() {
        // Uses its own counter so parallel tests cannot disturb it.
        static CALLS: AtomicUsize = AtomicUsize::new(0);
        fn counted(key: &[u8; 65], hash: &[u8; 32], signature: &[u8; 64]) -> bool {
            CALLS.fetch_add(1, Ordering::SeqCst);
            unsafe { package_p256_verify(key.as_ptr(), hash.as_ptr(), signature.as_ptr()) == 1 }
        }
        let good = fixture("good.vpk");
        let mut cache = Cache::new();
        for _ in 0..4 {
            assert_eq!(check(&good, TARGET, KEYS, sha256, counted, &mut cache), Ok(3));
        }
        assert_eq!(CALLS.load(Ordering::SeqCst), 1);
        let mut bad = good.clone();
        bad[HEADER] ^= 1;
        for _ in 0..2 {
            assert_eq!(check(&bad, TARGET, KEYS, sha256, counted, &mut cache), Err(Refusal::Signature));
        }
        assert_eq!(CALLS.load(Ordering::SeqCst), 3);
    }

    #[test]
    fn floors_refuse_older_packages_and_keep_fault_rollback() {
        let mut floors = Floors::new();
        // Before the factory catalog is read, an ID has floor 0: version 0 is still refused.
        assert!(!floors.boots(7, 0));
        // Factory catalog: Radio (7) at version 3, Audio (22) at 1.
        floors.factory(7, 3);
        floors.factory(22, 1);
        // An installed catalog boots at or above the factory version only.
        assert!(floors.boots(7, 3) && floors.boots(7, 4));
        assert!(!floors.boots(7, 2) && !floors.boots(7, 0));
        // Installs: equal or newer than what runs.
        floors.begin();
        floors.ran(7, 3);
        assert!(floors.installs(7, 3) && floors.installs(7, 5));
        assert!(!floors.installs(7, 2));
        // Radio 4 is installed, runs and stays healthy; then Radio 5.
        floors.begin();
        floors.ran(7, 4);
        floors.confirm();
        floors.begin();
        floors.ran(7, 5);
        // While 5 runs, even on trial, nothing older is installed.
        assert!(!floors.installs(7, 4) && !floors.installs(7, 3));
        assert!(floors.installs(7, 5) && floors.installs(7, 6));
        // It faults in its trial: the previous catalog (Radio 4) must still boot,
        assert!(floors.boots(7, 4));
        floors.begin();
        floors.ran(7, 4);
        // and a rebuilt Radio 4 can be installed over it: the version that
        // faulted and was thrown away left no floor behind.
        assert!(floors.installs(7, 4) && !floors.installs(7, 3));
        // Had Radio 5 stayed healthy, its floor would hold until power-off,
        // whatever catalog runs afterwards.
        floors.begin();
        floors.ran(7, 5);
        floors.confirm();
        floors.begin();
        floors.ran(7, 4);
        assert!(!floors.installs(7, 4) && floors.installs(7, 5));
        // A new boot image raises the factory floor: older banks no longer boot.
        let mut next = Floors::new();
        next.factory(7, 6);
        assert!(!next.boots(7, 5) && next.boots(7, 6) && !next.installs(7, 5));
        // IDs outside the table are refused, never indexed.
        assert!(!floors.boots(32, 1) && !floors.installs(u32::MAX, 1));
        floors.factory(40, 1);
        floors.ran(u32::MAX, 1);
        // An app ID absent from the factory catalog and never seen: any signed version installs.
        assert!(floors.boots(11, 1) && floors.installs(11, 1));
    }

    /// What the supervisor does to start a catalog: its packages, then its record.
    fn start(floors: &mut Floors, packages: &[(u32, u32)], record: &[u8]) {
        floors.begin();
        for (id, version) in packages {
            floors.ran(*id, *version);
        }
        floors.load(record);
    }

    #[test]
    fn a_removed_component_keeps_its_floor_across_a_reboot() {
        // The reviewers' case. Factory: Audio (22) at 1, no app 12. Audio 5
        // and app 12 at version 5 were installed and run.
        let factory = |floors: &mut Floors| {
            floors.factory(7, 3);
            floors.factory(22, 1);
        };
        let mut floors = Floors::new();
        factory(&mut floors);
        start(&mut floors, &[(7, 3), (12, 5), (22, 5)], &[]);
        floors.confirm();
        // Both are removed, one after the other. Each catalog the supervisor
        // writes carries the floors, including the component leaving it.
        let mut record = [0u8; Floors::RECORD];
        let len = floors.record(&mut record, 12, 0);
        assert_eq!(record_floor(&record[..len], 12), Some(5));
        assert_eq!(record_floor(&record[..len], 22), Some(5));
        // Radio is at its factory version: no entry.
        assert_eq!(record_floor(&record[..len], 7), Some(0));
        assert_eq!(len, 8 + 2 * 8);
        start(&mut floors, &[(7, 3), (22, 5)], &record[..len]);
        let len = floors.record(&mut record, 22, 0);
        assert_eq!(len, 8 + 2 * 8);
        let saved = record[..len].to_vec();
        // Power off and on: RAM is new, only the factory catalog and the
        // installed catalog (with its record) are left.
        let mut floors = Floors::new();
        factory(&mut floors);
        // Without the record the old packages would install again:
        assert!(floors.installs(12, 1) && floors.installs(22, 1));
        start(&mut floors, &[(7, 3)], &saved);
        // With it they do not, from the first moment the catalog runs.
        assert!(!floors.installs(12, 1) && !floors.installs(12, 4) && floors.installs(12, 5));
        assert!(!floors.installs(22, 1) && !floors.installs(22, 4) && floors.installs(22, 6));
        // The next catalog written (Radio 4 installed) still carries them.
        let len = floors.record(&mut record, 7, 4);
        assert_eq!(len, 8 + 3 * 8);
        for (id, floor) in [(7, 4), (12, 5), (22, 5), (1, 0)] {
            assert_eq!(record_floor(&record[..len], id), Some(floor));
        }
    }

    #[test]
    fn floor_records_are_exact_or_refused() {
        let mut floors = Floors::new();
        floors.factory(7, 3);
        // Nothing above the factory's versions: no record at all.
        let mut record = [0xeeu8; Floors::RECORD];
        assert_eq!(floors.record(&mut record, 7, 3), 0);
        assert_eq!(floors.record(&mut record, 7, 0), 0);
        // Too little room: nothing is written rather than a partial record.
        assert_eq!(floors.record(&mut record[..15], 7, 4), 0);
        let len = floors.record(&mut record, 7, 4);
        assert_eq!(&record[..len], [b"VFL1".as_slice(), &1u32.to_le_bytes(), &7u32.to_le_bytes(), &4u32.to_le_bytes()].concat());
        // Every ID above its floor still fits the stated maximum.
        for id in 0..Floors::IDS as u32 {
            floors.ran(id, 9);
        }
        assert_eq!(floors.record(&mut record, 0, 0), Floors::RECORD);
        assert_eq!(record_floor(&record, 31), Some(9));
        let mut two = record[..24].to_vec();
        two[4] = 2;
        assert_eq!(record_floor(&two, 1), Some(9));
        // Refused: empty, truncated, trailing bytes, wrong magic, a zero or
        // oversized count, a zero version, an ID out of range, IDs out of
        // order or repeated.
        assert_eq!(record_floor(&[], 1), None);
        assert_eq!(record_floor(&two[..23], 1), None);
        assert_eq!(record_floor(&[two.as_slice(), &[0; 4]].concat(), 1), None);
        let edit = |at: usize, value: u32| {
            let mut bad = two.clone();
            bad[at..at + 4].copy_from_slice(&value.to_le_bytes());
            record_floor(&bad, 1)
        };
        assert_eq!(edit(0, 0x314c_4657), None);
        assert_eq!(edit(4, 0), None);
        assert_eq!(edit(4, 3), None);
        assert_eq!(edit(4, 0x2000_0002), None);
        assert_eq!(edit(12, 0), None);
        assert_eq!(edit(16, 32), None);
        assert_eq!(edit(16, 0), None);
        assert_eq!(edit(8, 1), None);
        // A refused record changes no floor.
        let mut fresh = Floors::new();
        let mut bad = two.clone();
        bad[12..16].copy_from_slice(&0u32.to_le_bytes());
        fresh.load(&bad);
        fresh.load(&two[..23]);
        assert!(fresh.installs(0, 1) && fresh.installs(1, 1));
        fresh.load(&two);
        assert!(!fresh.installs(0, 8) && !fresh.installs(1, 8) && fresh.installs(1, 9));
    }

    #[test]
    fn a_fault_rejects_a_catalog_only_during_its_trial() {
        // A catalog found at power-on is not on trial: a crash restarts it.
        let mut trial = Trial::new();
        assert!(!trial.fault_rejects());
        // Just installed: the first fault rejects it, and whatever runs next
        // (the previous catalog) is not on trial.
        trial.installed();
        assert!(trial.fault_rejects());
        assert!(!trial.fault_rejects());
        // Installed and healthy for the whole period: no fault rejects it
        // afterwards, however many there are (the reviewers' downgrade).
        trial.installed();
        trial.healthy();
        for _ in 0..5 {
            assert!(!trial.fault_rejects());
        }
        // A second install starts a new trial.
        trial.installed();
        assert!(trial.fault_rejects());
    }

    #[test]
    fn detached_signatures_are_strict_der() {
        // The same signatures sign.py converts, checked against openssl's own DER.
        let dir = std::env::var("VPK_FIXTURES").expect("VPK_FIXTURES");
        let der = std::fs::read(format!("{dir}/detached.der")).unwrap();
        let message = std::fs::read(format!("{dir}/detached.bin")).unwrap();
        let key = KEYS.iter().find(|k| k.0 == 2).unwrap().1;
        let raw = der_signature(&der).expect("openssl DER");
        assert!(p256(&key, &sha256(&message), &raw));
        let mut other = message.clone();
        other[0] ^= 1;
        assert!(!p256(&key, &sha256(&other), &raw));
        // Truncated, extended, wrong tags and lengths.
        for cut in 0..der.len() {
            assert_eq!(der_signature(&der[..cut]), None, "cut {cut}");
        }
        assert_eq!(der_signature(&[der.as_slice(), &[0]].concat()), None);
        for (at, value) in [(0, 0x31), (1, der[1] + 1), (1, 0x81), (2, 3), (3, 0), (3, 34)] {
            let mut bad = der.clone();
            bad[at] = value;
            assert_eq!(der_signature(&bad), None, "byte {at} = {value}");
        }
        // Short and padded integers land right-aligned.
        let short = [0x30, 6, 2, 1, 5, 2, 1, 7];
        let raw = der_signature(&short).unwrap();
        assert!(raw[31] == 5 && raw[63] == 7 && raw.iter().filter(|b| **b != 0).count() == 2);
        // Negative integers and 33 bytes without a leading zero are refused.
        assert_eq!(der_signature(&[0x30, 6, 2, 1, 0x80, 2, 1, 7]), None);
        let mut long = vec![0x30, 38, 2, 33, 1];
        long.extend([0u8; 32]);
        long.extend([2, 1, 7]);
        assert_eq!(der_signature(&long), None);
    }
}
